// Upright solver invariants (GAL-DEV-07). The engine's keystone model
// (develop.rs geometry_transform_buf) maps a source-vertical line at u = x−0.5
// to destination tilt −V·u − tanθ and a source-horizontal line at c = y−0.5 to
// slope −H·c + tanθ (θ = rotate·15°, unit-square space). Feeding lines/images
// generated by that forward model into the solvers must recover the NEGATED
// parameters — the correction that cancels the warp.

import { describe, expect, it } from "vitest";

import {
  TRANSFORM_SECTIONS,
  UPRIGHT_MODES,
  solveGuidedUpright,
  solveUpright,
  type UprightLine,
} from "./DevelopPanels";

const tiltOfVertical = (u: number, V: number, theta: number) => -V * u - Math.tan(theta);
const slopeOfHorizontal = (c: number, H: number, theta: number) => -H * c + Math.tan(theta);
/** θ (radians) → the engine's rotate slider value. */
const rotParam = (theta: number) => (theta * 180) / Math.PI / 15;

/** Guide lines a user would draw along warped verticals + horizontals. */
function guidedLines(V: number, H: number, theta: number): UprightLine[] {
  const lines: UprightLine[] = [];
  for (const u of [-0.3, 0.3]) {
    const t = tiltOfVertical(u, V, theta);
    lines.push({ x0: u + 0.5 - t * 0.4, y0: 0.1, x1: u + 0.5 + t * 0.4, y1: 0.9 });
  }
  for (const c of [-0.25, 0.25]) {
    const s = slopeOfHorizontal(c, H, theta);
    lines.push({ x0: 0.1, y0: c + 0.5 - s * 0.4, x1: 0.9, y1: c + 0.5 + s * 0.4 });
  }
  return lines;
}

/** Anti-aliased dark lines on white — the smooth ramp is what lets the Sobel
 *  orientation carry the true line angle (mirrors a downscaled photo). */
function drawLines(
  w: number,
  h: number,
  lineX: ((yn: number) => number)[],
  lineY: ((xn: number) => number)[],
): { data: Uint8ClampedArray; width: number; height: number } {
  const data = new Uint8ClampedArray(w * h * 4);
  for (let y = 0; y < h; y++) {
    const yn = (y + 0.5) / h;
    for (let x = 0; x < w; x++) {
      const xn = (x + 0.5) / w;
      let d = Infinity;
      for (const fx of lineX) d = Math.min(d, Math.abs(xn - fx(yn)) * w);
      for (const fy of lineY) d = Math.min(d, Math.abs(yn - fy(xn)) * h);
      const v = Math.round(255 * Math.min(1, d / 2));
      const i = (y * w + x) * 4;
      data[i] = data[i + 1] = data[i + 2] = v;
      data[i + 3] = 255;
    }
  }
  return { data, width: w, height: h };
}

describe("Transform panel surface", () => {
  it("exposes LR's full slider set and the six Upright modes", () => {
    expect(TRANSFORM_SECTIONS.flatMap((s) => s.specs).map((s) => s.key)).toEqual([
      "vertical", "horizontal", "rotate", "aspect", "scale", "xOffset", "yOffset",
    ]);
    expect(UPRIGHT_MODES.map((m) => m.key)).toEqual(["off", "auto", "level", "vertical", "full", "guided"]);
  });
});

describe("solveGuidedUpright", () => {
  it("recovers the negated warp parameters from four guide lines", () => {
    const V = 0.6;
    const H = -0.4;
    const theta = (3 * Math.PI) / 180;
    const s = solveGuidedUpright(guidedLines(V, H, theta));
    expect(s.vertical).toBeCloseTo(-V, 1);
    expect(s.horizontal).toBeCloseTo(-H, 1);
    expect(s.rotate).toBeCloseTo(-rotParam(theta), 1);
  });

  it("a single vertical guide straightens only (no keystone)", () => {
    // Line leaning left going down: tilt = (0.5 − 0.55) / 0.8 < 0.
    const s = solveGuidedUpright([{ x0: 0.55, y0: 0.1, x1: 0.5, y1: 0.9 }]);
    expect(s.vertical).toBe(0);
    expect(s.horizontal).toBe(0);
    expect(s.rotate).toBeLessThan(0);
  });
});

describe("solveUpright (image analysis)", () => {
  it("Vertical mode counters converging verticals", () => {
    const V = 0.5;
    const img = drawLines(
      240,
      240,
      [-0.3, -0.1, 0.1, 0.3].map((u) => (yn: number) => u + 0.5 + tiltOfVertical(u, V, 0) * (yn - 0.5)),
      [],
    );
    const s = solveUpright("vertical", img)!;
    expect(s.vertical).toBeLessThan(-0.2); // opposes the warp, right sign
    expect(s.vertical).toBeGreaterThan(-0.8);
    expect(Math.abs(s.rotate)).toBeLessThan(0.15);
    expect(s.horizontal).toBe(0); // Vertical mode never touches Horizontal
  });

  it("Level mode straightens a uniformly tilted horizon", () => {
    const theta = (4 * Math.PI) / 180;
    const img = drawLines(
      240,
      240,
      [],
      [-0.25, 0, 0.25].map((c) => (xn: number) => c + 0.5 + slopeOfHorizontal(c, 0, theta) * (xn - 0.5)),
    );
    const s = solveUpright("level", img)!;
    expect(s.vertical).toBe(0);
    expect(s.horizontal).toBe(0);
    expect(s.rotate).toBeLessThan(-0.1); // −4°/15 ≈ −0.27
    expect(s.rotate).toBeGreaterThan(-0.45);
  });

  it("Auto applies a damped Full correction", () => {
    const V = 0.5;
    const img = drawLines(
      240,
      240,
      [-0.3, -0.1, 0.1, 0.3].map((u) => (yn: number) => u + 0.5 + tiltOfVertical(u, V, 0) * (yn - 0.5)),
      [],
    );
    const full = solveUpright("full", img)!;
    const auto = solveUpright("auto", img)!;
    expect(auto.vertical).toBeCloseTo(0.85 * full.vertical, 5);
    expect(Math.abs(auto.vertical)).toBeLessThan(Math.abs(full.vertical));
  });
});
